def md(name,text): (OUT/name).write_text(text.rstrip()+'\n',encoding='utf-8',newline='\n')
def aggregate():
    results=[];rows=[];co=[]
    for s in ['development','later']:
        z=json.loads((OUT/'empirical'/s/'results.json').read_text());results.extend(z['results'])
        rows.append(pd.read_parquet(OUT/'empirical'/s/'paired-error-deltas.parquet'))
        co.extend(json.loads((OUT/'empirical'/s/'coefficients-and-gain.json').read_text()))
    f=pd.concat(rows,ignore_index=True);summary=[];stability=[]
    for (sport,role,family),g in f.groupby(['sport','role','family']):
        deltas={k:float(g[k].mean()) for k in ['marginMAE','totalMAE','scoreMAE','homeMAE','awayMAE']}
        summary.append(dict(sport=sport,role=role,family=family,games=len(g),delta=deltas,interval95={k:ci(g[k],g.date,9152601) for k in ['marginMAE','totalMAE','scoreMAE']}))
        for variable in ['season','support','favoriteSide']:
            for value,gg in g.groupby(variable):stability.append(dict(sport=sport,role=role,family=family,axis=variable,group=str(value),n=len(gg),marginDelta=float(gg.marginMAE.mean()),totalDelta=float(gg.totalMAE.mean()),homeDelta=float(gg.homeMAE.mean()),awayDelta=float(gg.awayMAE.mean())))
        for team in sorted(set(g.home_team)|set(g.away_team)):
            gg=g[(g.home_team==team)|(g.away_team==team)]
            if len(gg)>=20:stability.append(dict(sport=sport,role=role,family=family,axis='team',group=team,n=len(gg),marginDelta=float(gg.marginMAE.mean()),totalDelta=float(gg.totalMAE.mean()),homeDelta=float(gg.homeMAE.mean()),awayDelta=float(gg.awayMAE.mean())))
    coeff=[r for r in co if 'standardizedMargin' in r];coef=pd.DataFrame(coeff);signs=[]
    for (s,n),g in coef.groupby(['sport','feature']):
        for col in ['standardizedMargin','standardizedTotal']:
            v=g[col].to_numpy(); signs.append(dict(sport=s,feature=n,channel=col,signChanges=bool((v>.01).any() and (v<-.01).any()),min=float(v.min()),max=float(v.max()),qualification='Coefficient sign under collinearity is not causal; near-zero threshold .01 is descriptive.'))
    save(OUT/'FEATURE_IMPORTANCE_AND_ABLATION.json',dict(schema='MULTISPORT_GROUPED_PERMUTATION_V1',createdAtUtc=now(),method=ref(OUT/'EMPIRICAL_DESIGN.json'),developmentReview=ref(OUT/'DEVELOPMENT_REVIEW.json'),summary=summary,seasonResults=results,stability=stability,coefficientStability=signs,
      direction='Positive perturbed-minus-baseline error means destroying this information hurt the frozen point model. Negative does not establish drop-column refit improvement.',
      properScoreCoverage={'NBA':'Independent Elo probability diagnostics invariant; point ablations do not replace Elo.','NFL':'Native normal-margin proxy binary scores, excluding ties; not operational joint winner probability or NFL three-class Brier.','CFB':'Fixed Development-trained logistic margin calibration only in later periods. Development probabilities unavailable.','energyCRPS':'Unavailable: no distribution family changed or simulated; point perturbations are not a distribution comparison.'},
      skipped={'MLB':'No proper-score importance test: frozen fold includes2026 fitted evidence and prior chronology is uncertified. No permitted earlier independent matrix/model pair established without reopening historical studies. No MLB outcome access.','SHAP':'Not needed for bounded grouped reliance; descriptive NFL tree gain retained, no individual gain ranking.','dropColumnRefits':'None; grouped inference permutation performed instead. Correlation can inflate or conceal measured reliance.'},
      operationalM1Qualification='NFL assessment models are chronological fixed-recipe research clones using earlier seasons, not retrospective execution of the 2026 published all-history refit. Research clones are serialized and cannot replace production through this script.',
      exclusions='NBA no neutral targets; CFB primary FBS-v-FBS regular finals; NFL REG/POST-coded eligible Gold subset (actual retained cohort REG only). Calendar2026 labels excluded. ACCESS_EXCEPTION.json discloses earlier accidental snapshot exposure.',
      noSignificanceFishing='All predeclared families and subgroups retained. Many correlated comparisons; intervals descriptive, no multiplicity-adjusted discovery claim.'))
    return summary,stability

